/** A large mock file to push Typescript to its limits with `defineApi`. */

import {assert} from '@augment-vir/assert';
import {HttpMethod, HttpStatus} from '@augment-vir/common';
import {describe, it} from '@augment-vir/test';
import {type BaseRoutePath, defineApi, defineEndpoint, defineWebSocket} from '@rest-vir/api';
import {defineShape, enumShape} from 'object-shape-tester';
import {structuredRenderDataShape} from 'structured-render';

export enum AuthLevel {
    Required = 'required',
    Any = 'any',
    Blocked = 'blocked',
    Admin = 'admin',
}

const customProps = {
    requiredAuth: enumShape(AuthLevel),
};

export const endpoint0 = defineEndpoint({
    path: '/reports/item-0',
    requests: {
        [HttpMethod.Post]: {
            customProps,
            requestData: defineShape({
                id: '',
                payload: structuredRenderDataShape,
            }),
            responses: {
                [HttpStatus.Ok]: {
                    responseData: defineShape({
                        id: '',
                        result: structuredRenderDataShape,
                    }),
                },
            },
        },
    },
});

